use std::{io::Write,path::Path};
use rrrah_dedup::{linear::LinearRgbaView,local::LocalPolicy,pyramid::PyramidPolicy,gradient::{extract_gradient_pyramid_with_recipe,GradientCellRecipe}};
fn main(){let args:Vec<_>=std::env::args().skip(1).collect();assert_eq!(args.len(),2);let bytes=std::fs::read(&args[0]).unwrap();let w=u32::from_le_bytes(bytes[..4].try_into().unwrap());let h=u32::from_le_bytes(bytes[4..8].try_into().unwrap());let count=u64::from(w)*u64::from(h);assert!(count<=12800000);assert_eq!(bytes.len(),8+count as usize*16);let pixels:Vec<f32>=bytes[8..].chunks_exact(4).map(|b|f32::from_le_bytes(b.try_into().unwrap())).collect();let view=LinearRgbaView::new(w,h,&pixels,12800000,||false).unwrap();let local=LocalPolicy{max_pixels:12800000,max_candidates:12800000,max_features:1024,minimum_corner_score:0.0001};let policy=PyramidPolicy{local,max_levels:3,max_total_pixels:12800000,max_total_features:3072};let mut bank=extract_gradient_pyramid_with_recipe(&view,policy,3072*512,GradientCellRecipe::Interpolated,||false).unwrap();let extracted=bank.len();bank.truncate(2048);let mut output=std::fs::OpenOptions::new().write(true).create_new(true).open(Path::new(&args[1])).unwrap();output.write_all(&(bank.len()as u64).to_le_bytes()).unwrap();for f in &bank{for v in f.position.iter().chain(&f.descriptor.0){output.write_all(&v.to_bits().to_le_bytes()).unwrap();}}println!("{} {} {} {}",w,h,extracted,bank.len());}
